TEST(FeildStatDynamicAPI, AllConditions)
{
	int n_thread = 0;
	int n_loops = 0;

	for(int i = 0; i < 5; i++)
	{
		n_thread = 1 << i;
		for(int j = 0; j < 6; j++)
		{
			n_loops = (int)pow(10, (double)j);
			fieldstat_dynamic_benchmark(n_thread, n_loops);
		}
	}
}



